import{z as i,x as A,o as E,c as B,q as s,j as l,D as o,d as r,s as d,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"错误恢复","description":"","frontmatter":{"title":"错误恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/parse-error-recovery.md","filePath":"cs/parse-error-recovery.md","lastUpdated":1791413859000}'),p={name:"cs/parse-error-recovery.md"};function c(h,e,u,m,D,C){const t=A("Mermaid");return E(),B("div",null,[e[2]||(e[2]=s('<h1 id="错误恢复" tabindex="-1">错误恢复 <a class="header-anchor" href="#错误恢复" aria-label="Permalink to &quot;错误恢复&quot;">​</a></h1><div class="epigraph"><p>分析器的职责不止于第一个非法记号：要报告、要跳到能再同步的符号，并尽量不引发雪崩式误报。</p><footer>—— 据龙书第 4 章错误恢复；Burke and Fisher, A Practical Method for LR and LL Syntax Error Diagnosis and Recovery 整理</footer></div><p>上一课<a href="/cs/pratt-parsing">Pratt</a>在合法表达式上漂亮。真实编译器面对缺括号、多逗号。主干 LL 课点过 FOLLOW 作同步集。缺口是<strong>恢复策略</strong>：恐慌模式、短语级修补、yacc 的 <code>error</code> 记号。本课钉「报告一次、跳过、继续」，不把 IDE 的红线协议写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>查表空或 nud 缺失：输入不是语言的前缀。若立刻 <code>exit</code>，用户只看见第一处。若胡乱插入记号，后续整棵树错位，报错上百条。缺口是<strong>同步</strong>：丢弃直到遇见 <code>;</code>、<code>}</code> 或 FOLLOW 中的记号，使栈与输入再次对齐。</p><p>yacc：<code>error</code> 产生式允许在某非终结符下吃掉错误短语。bison 的 <code>yyerrok</code> 解除「刚恢复」抑制，避免相邻错误被吞。</p><p><span class="marginnote">「恐慌模式」名字吓人，做法却是最朴素的止损：不试图猜用户想写什么，直接把记号一个个丢掉，直到遇见 <code>;</code>、<code>}</code> 这类结构性「路标」再重新对齐继续。类比：开车错过出口时不原地掉头，而是开到下一个能调头的路口。</span></p><h3 id="同步不是「猜对用户意思」" tabindex="-1">同步不是「猜对用户意思」 <a class="header-anchor" href="#同步不是「猜对用户意思」" aria-label="Permalink to &quot;同步不是「猜对用户意思」&quot;">​</a></h3><p>恢复后的 AST 可以残缺，类型检查必须能容忍空洞节点。不要在恢复里做复杂程序变换。语义动作里申请的内存要能在弹出栈时释放——上一课 yacc 已点过所有权。</p><p><span class="marginnote">龙书 4.1.4 与 4.5.5。Burke–Fisher 讨论 LR/LL 诊断。本课不把 GLR 多栈恢复写成算法作业。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>恐慌：从当前记号丢到同步集。短语级：尝试插入/删除一个记号看能否继续（限一步，防组合爆炸）。错误产生式：文法里显式 <code>error</code>。统一：每个语法错误一条主诊断，带行号；恢复后计数，太多则停。</p>',12)),(E(),l(n,null,{default:o(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ERR%5B%22%E9%9D%9E%E6%B3%95%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%22%5D%0A%20%20REP%20--%3E%20SYNC%5B%22%E4%B8%A2%E5%BC%83%E8%87%B3%E5%90%8C%E6%AD%A5%E9%9B%86%22%5D%0A%20%20SYNC%20--%3E%20CONT%5B%22%E7%BB%A7%E7%BB%AD%E5%88%86%E6%9E%90%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"词法错误（非法字符）在 lex 动作里吞掉一字并警告，不要把垃圾字符送进语法栈。",-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,[r("雪崩：缺一个 "),a("code",null,")"),r(" 会导致整份参数列表全部「期望逗号」。抑制：同一行或同一子树只报一次。LR 比 LL 更难点「期望什么」：状态里有多条项。实用做法：列出该状态可移进的记号集合，截断显示。")],-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},[r("雪崩直觉：像改试卷时把第 1 题的答案抄串了行，于是第 2–10 题全被判错——错的其实是判卷方式，不是答案。数字实例："),a("code",null,"f(1, 2 3, 4)"),r(" 少个逗号，没有抑制的解析器可以对同一参数列表连报五六条「期望逗号」，而真正的错误只有一处。")])],-1)),(E(),l(n,null,{default:o(()=>[d(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%22%E6%BA%90%E7%A0%81%E7%BC%BA%E4%B8%80%E4%B8%AA%E5%8F%B3%E6%8B%AC%E5%8F%B7%22%5D%20--%3E%20B2%5B%22%E6%A0%88%E4%B8%8E%E8%BE%93%E5%85%A5%E9%94%99%E4%BD%8D%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E5%90%8E%E7%BB%AD%E6%AF%8F%E4%B8%AA%E8%AE%B0%E5%8F%B7%E9%83%BD%E8%AF%AF%E6%8A%A5%EF%BC%9A%E6%9C%9F%E6%9C%9B%E9%80%97%E5%8F%B7%22%5D%0A%20%20B3%20--%3E%20C1%5B%22%E5%90%8C%E6%AD%A5%EF%BC%9A%E4%B8%A2%E5%BC%83%E8%87%B3%20FOLLOW%20%E8%AE%B0%E5%8F%B7%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E6%8A%91%E5%88%B6%EF%BC%9A%E5%90%8C%E4%B8%80%E5%AD%90%E6%A0%91%E5%8F%AA%E6%8A%A5%E4%B8%80%E6%AC%A1%22%5D%0A%20%20C2%20--%3E%20OK%5B%22%E6%81%A2%E5%A4%8D%EF%BC%9A%E5%89%A9%E4%BD%99%E4%BB%A3%E7%A0%81%E6%AD%A3%E5%B8%B8%E6%8A%A5%E5%91%8A%E7%9C%9F%E5%AE%9E%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=s('<p>PEG 的有序选择把失败藏在左枝，诊断要另记最深失败位置（Ford 也讨论过误差报告），与 LR 的 FOLLOW 不同源。</p><p><span class="marginnote">初学者容易以为编译器该「总能猜出你想写什么」。恢复的契约其实低得多：进程不崩、报错的位置可信、其余代码还能继续检查。残缺的 AST 会被后续类型检查明确拒绝，而不是被当成合法程序误优化。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 tree-sitter 的增量，不算最小编辑距离的全局最优修补。后课默认：前端能在错误后同步并继续建残树。下一课：编辑器里改一个字符不必重头分析——增量解析。</p><p>不要承诺「总能恢复成用户意图」。恢复的契约是：编译器进程不崩，诊断位置可信。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恢复 = 报告 + 同步 + 抑制雪崩。</li><li><code>error</code> 记号与 FOLLOW 同步是两条实用路。</li><li>残树必须让后遍可拒绝而非误优化。</li><li>出处：Aho et al., 龙书；Burke and Fisher。</li></ul>',7))])}const L=i(p,[["render",c]]);export{f as __pageData,L as default};
